import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { login, register } from '../services/api';

const Login = () => {
  const [isRegister, setIsRegister] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    try {
      if (isRegister) {
        await register(username, password);
        setIsRegister(false); // Switch to login after register
        alert("Registration successful! Please login.");
      } else {
        const data = await login(username, password);
        localStorage.setItem('token', data.access_token);
        // Force redirect to dashboard
        window.location.href = '/dashboard';
      }
    } catch (err) {
      setError('Authentication failed. Check credentials or backend.');
    }
  };

  return (
    <div className="flex items-center justify-center h-screen bg-scifi-bg text-neon-green font-mono">
      <div className="w-96 p-8 border border-neon-green/30 rounded-lg bg-scifi-panel shadow-[0_0_30px_rgba(0,255,157,0.1)] relative">
        
        {/* Glowing Top Border */}
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-neon-green to-transparent opacity-80"></div>

        <h1 className="text-3xl font-bold mb-8 text-center tracking-[0.2em] text-white">QS-VAULT</h1>
        
        <form onSubmit={handleSubmit} className="flex flex-col gap-5">
          <div className="flex flex-col gap-1">
             <label className="text-[10px] uppercase text-gray-500 tracking-wider">Identity</label>
             <input
                type="text"
                className="p-3 bg-black border border-gray-700 focus:outline-none focus:border-neon-green text-white rounded transition-all placeholder-gray-800"
                placeholder="Enter Username"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
              />
          </div>
          
          <div className="flex flex-col gap-1">
             <label className="text-[10px] uppercase text-gray-500 tracking-wider">Passcode</label>
             <input
                type="password"
                className="p-3 bg-black border border-gray-700 focus:outline-none focus:border-neon-green text-white rounded transition-all placeholder-gray-800"
                placeholder="Enter Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
          </div>

          {error && <p className="text-red-500 text-xs border border-red-500/20 bg-red-900/10 p-2 rounded text-center">{error}</p>}
          
          <button type="submit" className="mt-4 p-3 bg-neon-green hover:bg-white hover:text-black text-black font-bold uppercase tracking-wider rounded shadow-[0_0_15px_rgba(0,255,157,0.4)] transition-all duration-300">
            {isRegister ? 'Initialize Identity' : 'Access Gateway'}
          </button>
        </form>
        
        {/* UPDATED: Bold Register Link */}
        <div className="mt-8 text-center border-t border-gray-800 pt-4">
          <p className="text-xs text-gray-500 mb-2">
            {isRegister ? "Already have access?" : "First time user?"}
          </p>
          <button 
            className="text-sm font-bold text-neon-green hover:text-white tracking-wide uppercase border-b border-transparent hover:border-neon-green transition-all"
            onClick={() => setIsRegister(!isRegister)}
          >
            {isRegister ? "Return to Login" : ">>> Register New Identity <<<"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Login;
